// Portable document model shared by the studio, web export and Android runtime.
export const sceneTypes=['frame','section','grid','menu','hamburger','slider','slide','hero','form','text','image','button','rectangle','ellipse','line','input','icon'];
export const sceneContainerTypes=['frame','section','grid','menu','hamburger','slider','slide','hero','form'];
export const isSceneContainer=node=>!!node&&sceneContainerTypes.includes(node.type);
export const sceneId=()=> 'n'+Array.from(crypto.getRandomValues(new Uint8Array(8)),n=>n.toString(16).padStart(2,'0')).join('');
export const sceneEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
