export function sceneAppearanceDefaults(){return {backgroundType:'solid',gradientFrom:'#7c5cf0',gradientTo:'#39c8cf',gradientAngle:135,backgroundImage:'',backgroundSize:'cover',backgroundPosition:'center',texture:'dots',textureColor:'#8b80ad',textureScale:24,textureOpacity:20,blur:0,backdropBlur:0,glass:false,glassOpacity:18,shadow:'none',shadowX:0,shadowY:8,shadowBlur:24,shadowSpread:0,shadowColor:'#000000',shadowOpacity:20,shadowInset:false,contentH:'auto',contentV:'auto'};}
