export function sceneEffectsStyle(n){const a=normalizeSceneAppearance(n),shadow=a.shadow==='soft'?'0 4px 16px #00000014':a.shadow==='deep'?'0 12px 32px #00000030':a.shadow==='custom'?`${a.shadowInset?'inset ':''}${a.shadowX}px ${a.shadowY}px ${a.shadowBlur}px ${a.shadowSpread}px ${sceneRGBA(a.shadowColor,a.shadowOpacity)}`:'none',backdrop=a.backdropBlur||(a.glass?18:0);return `box-shadow:${shadow};${a.blur?`filter:blur(${a.blur}px);`:''}${backdrop?`-webkit-backdrop-filter:blur(${backdrop}px);backdrop-filter:blur(${backdrop}px);`:''}`;}
