export const commerceActions=['cart-add','cart-plus','cart-minus','cart-remove','favorite','place-order','variant-size','variant-color','apply-filters','clear-filters','profile-save'];
export const commerceRoles=['product-card','promo-coffee','promo-swim','cart-row','cart-cta','cart-total','cart-subtotal','cart-quantity','cart-badge','cart-empty','cart-items','favorites-empty','favorite-card','order-summary','order-id','profile-name','search','filter-rating','filter-size','filter-color','filter-brand','checkout-name','checkout-phone','checkout-address','checkout-city','checkout-postal','checkout-payment','checkout-error'];
export function sceneMix(a,b,ratio){const parse=s=>{s=String(s||'#000000').slice(1);if(s.length===3)s=s.split('').map(c=>c+c).join('');return [0,2,4].map(i=>parseInt(s.slice(i,i+2),16)||0);};return '#'+parse(a).map((v,i)=>Math.round(v+(parse(b)[i]-v)*ratio).toString(16).padStart(2,'0')).join('');}
