export function normalizeCommerce(c){if(!c||!Array.isArray(c.products))return null;return {key:String(c.key||'shop').slice(0,150),template:String(c.template||'').slice(0,30),currency:c.currency==='USD'?'USD':'IRT',products:c.products.slice(0,30).filter(p=>p&&/^[a-z\d-]{1,50}$/i.test(String(p.id||''))).map(p=>({id:String(p.id||'').slice(0,50),title:String(p.title||'').slice(0,150),category:String(p.category||'').slice(0,80),price:sceneNumber(p.price,0,0,1e12),image:sceneURL(p.image),imageCrop:normalizeImageCrop(p.imageCrop),rating:sceneNumber(p.rating,4.5,0,5),stock:sceneNumber(p.stock,15,0,10000),brand:String(p.brand||'FORM').slice(0,60),sizes:Array.isArray(p.sizes)?p.sizes.slice(0,12).map(v=>String(v).slice(0,30)):[],colors:Array.isArray(p.colors)?p.colors.slice(0,12).map(v=>String(v).slice(0,30)):[]}))};}
