 const submit=e=>{const form=e.target.closest('[data-scene-form]');if(!form||form.dataset.commerceForm)return;e.preventDefault();if(!form.reportValidity())return;const status=form.querySelector('.scene-form-status'),fields=[...form.querySelectorAll('[data-field-node]')].map(el=>({id:el.dataset.fieldNode,label:el.dataset.fieldLabel,value:el.type==='checkbox'?el.checked:el.value.slice(0,10000)}));if(preview){status.textContent='پیش‌نمایش فرم: اطلاعات ارسال یا ذخیره نشد.';return;}if(form.dataset.submitMode==='email'){if(!form.dataset.formEmail){status.textContent='ایمیل دریافت‌کننده تنظیم نشده است.';return;}const body=fields.map(f=>f.label+': '+f.value).join('\n');location.href='mailto:'+encodeURIComponent(form.dataset.formEmail)+'?subject='+encodeURIComponent('پاسخ فرم')+'&body='+encodeURIComponent(body);status.textContent='برای ارسال، پیام را در برنامه ایمیل تأیید کنید.';return;}try{const key='scene.responses:'+storageKey+':'+form.dataset.sceneForm;let previous=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(previous))previous=[];previous.push({time:Date.now(),fields});localStorage.setItem(key,JSON.stringify(previous.slice(-100)));status.textContent=form.dataset.success||'پاسخ شما روی همین دستگاه ثبت شد.';form.reset();}catch{status.textContent='ذخیره اطلاعات ناموفق بود؛ فضای دستگاه را بررسی کنید.';}};
 const down=e=>{const view=e.target.closest('[data-slider]');if(view&&!e.target.closest('input,textarea,button,a'))swipe={view,x:e.clientX,y:e.clientY};};
 const up=e=>{if(!swipe)return;const {view,x,y}=swipe;swipe=null;const dx=e.clientX-x,dy=e.clientY-y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))slide(view,Number(view.dataset.slideIndex||0)+(dx>0?1:-1));};
