export function mountScene(scene,root,{preview=false}={}){let current=scene.pages.find(p=>p.id===scene.startPage)||scene.pages[0],dispose=null;const render=()=>{dispose?.();const hasMenu=current.children.flatMap(sceneDescendants).some(n=>n.visible&&['menu','hamburger'].includes(n.type));root.className='scene-runtime';const fixed=[];const collect=nodes=>{for(const n of nodes){if(!n.visible)continue;if(n.position==='fixed')fixed.push(n);else collect(n.children||[]);}};collect(current.children);root.style.setProperty('--scene-display-width',Math.min(window.innerWidth,current.w)+'px');root.innerHTML=renderScenePage(current,{skipFixed:true})+fixed.map(n=>renderSceneNode(n,'column',false)).join('')+(!hasMenu&&!scene.commerce&&scene.pages.length>1?`<nav class="scene-page-nav">${scene.pages.map(p=>`<button data-scene-page="${sceneEscape(p.id)}" class="${p.id===current.id?'active':''}">${sceneEscape(p.name)}</button>`).join('')}</nav>`:'');const frame=root.querySelector('.scene-page');if(frame)frame.style.zoom=Math.min(1,window.innerWidth/current.w);dispose=bindSceneInteractions(root,{scene,preview,storageKey:scene.commerce?.key||scene.startPage,onPage:id=>{const next=scene.pages.find(p=>p.id===id);if(next){current=next;render();window.scrollTo(0,0);}}});};render();window.addEventListener('resize',()=>{const frame=root.querySelector('.scene-page');if(frame)frame.style.zoom=Math.min(1,window.innerWidth/current.w);root.style.setProperty('--scene-display-width',Math.min(window.innerWidth,current.w)+'px');});}
