export function emptyCommerceState(){return {cart:{},favorites:[],variants:{},filters:{},query:'',profile:'uix.vikram',orders:[]};}
export function normalizeCommerceState(raw,products){const state=emptyCommerceState(),ids=new Set(products.map(p=>p.id));if(!raw||typeof raw!=='object')return state;for(const id of ids){const quantity=Math.floor(sceneNumber(raw.cart?.[id],0,0,99));if(quantity)state.cart[id]=quantity;if(raw.variants?.[id])state.variants[id]={size:String(raw.variants[id].size||'').slice(0,30),color:String(raw.variants[id].color||'').slice(0,30)};}state.favorites=Array.isArray(raw.favorites)?[...new Set(raw.favorites.filter(id=>ids.has(id)))]:[];for(const key of ['rating','size','color','brand'])state.filters[key]=String(raw.filters?.[key]||'').slice(0,60);state.query=String(raw.query||'').slice(0,200);state.profile=String(raw.profile||'uix.vikram').slice(0,80);state.orders=Array.isArray(raw.orders)?raw.orders.slice(0,30).filter(o=>o&&typeof o.id==='string'&&Array.isArray(o.items)).map(o=>({id:o.id.slice(0,60),createdAt:Number(o.createdAt)||0,total:sceneNumber(o.total,0,0,1e14),status:'local',shipping:Object.fromEntries(['name','phone','address','city','postal','payment'].map(key=>[key,String(o.shipping?.[key]||'').slice(0,500)])),items:o.items.slice(0,30).map(item=>({title:String(item.title||'').slice(0,150),quantity:sceneNumber(item.quantity,1,1,99),price:sceneNumber(item.price,0,0,1e12),size:String(item.size||'').slice(0,30),color:String(item.color||'').slice(0,30)}))})):[];return state;}
export function commerceTotal(state,products){return products.reduce((total,p)=>total+p.price*(state.cart[p.id]||0),0);}
export function commerceMatches(product,query,filters={}){const q=String(query||'').trim().toLowerCase();return (!q||[product.title,product.category,product.brand].some(value=>String(value||'').toLowerCase().includes(q)))&&(!filters.rating||product.rating>=parseCommercePrice(filters.rating))&&(!filters.brand||product.brand===filters.brand)&&(!filters.color||product.colors?.includes(filters.color))&&(!filters.size||product.sizes?.includes(filters.size));}
export function bindSceneCommerce(root,{scene,onPage,preview=false}){
 const commerce=scene.commerce,en=scene.pages[0].direction==='ltr',t=(fa,eng)=>en?eng:fa,products=commerce.products,storageKey='app-commerce:'+commerce.key,key=(preview?'preview:':'live:')+storageKey;
 let state;if(root._sceneCommerce?.key===key)state=root._sceneCommerce.state;else{let raw=null;if(!preview)try{raw=JSON.parse(localStorage.getItem(storageKey)||'null');}catch{}state=normalizeCommerceState(raw,products);if(!en){state.profile=persianCommerceText(state.profile);for(const key of Object.keys(state.filters))state.filters[key]=persianCommerceText(state.filters[key]);for(const variant of Object.values(state.variants))for(const key of ['size','color'])variant[key]=persianCommerceText(variant[key]);}root._sceneCommerce={key,state};}
 const money=amount=>commerce.currency==='USD'?(en?'$'+amount.toFixed(2):amount.toLocaleString('fa-IR',{minimumFractionDigits:2})+' دلار'):amount.toLocaleString('fa-IR')+' تومان',getProduct=id=>products.find(p=>p.id===id);
 const showStatus=message=>{let status=root.querySelector('.commerce-status');if(!status){status=document.createElement('div');status.className='commerce-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');root.append(status);}status.textContent=message;};
 const persist=()=>{if(preview)return true;try{localStorage.setItem(storageKey,JSON.stringify(state));return true;}catch{showStatus(t('فضای ذخیره دستگاه کافی نیست.','Device storage is full.'));return false;}};
 const setText=(node,value)=>{const label=node.querySelector('[data-scene-text]');if(label)label.textContent=en||node.dataset.commerceRole==='order-id'?value:persianCommerceText(value);};
 const role=name=>[...root.querySelectorAll('[data-commerce-role="'+name+'"]')];
 function refresh(){const total=commerceTotal(state,products),quantity=Object.values(state.cart).reduce((a,b)=>a+b,0),last=state.orders[0];
 for(const node of role('cart-row'))node.hidden=!state.cart[node.dataset.itemId];for(const node of role('cart-quantity'))setText(node,en?String(state.cart[node.dataset.itemId]||0):persianDigits(state.cart[node.dataset.itemId]||0));for(const node of role('cart-subtotal'))setText(node,money((getProduct(node.dataset.itemId)?.price||0)*(state.cart[node.dataset.itemId]||0)));for(const node of role('cart-total'))setText(node,money(total));for(const node of role('cart-cta'))setText(node,t('سبد خرید','View your cart')+'    '+quantity+'x    '+money(total));for(const node of role('cart-badge')){setText(node,en?String(quantity):persianDigits(quantity));node.hidden=quantity===0;}for(const node of role('cart-empty'))node.hidden=quantity>0;
 for(const node of role('product-card')){const p=getProduct(node.dataset.itemId);node.hidden=!!p&&!commerceMatches(p,state.query,state.filters);}for(const node of role('favorite-card'))node.hidden=!state.favorites.includes(node.dataset.itemId);for(const node of role('favorites-empty'))node.hidden=state.favorites.length>0;
 for(const button of root.querySelectorAll('[data-commerce-action="favorite"]')){const picked=state.favorites.includes(button.dataset.itemId);button.setAttribute('aria-pressed',String(picked));const svg=button.querySelector('svg');if(svg)svg.style.fill=picked?'currentColor':'none';}
 for(const button of root.querySelectorAll('[data-commerce-action^="variant-"]')){const value=state.variants[button.dataset.itemId]?.[button.dataset.commerceAction==='variant-size'?'size':'color'];button.setAttribute('aria-pressed',String(value===button.dataset.actionValue));button.classList.toggle('commerce-picked',value===button.dataset.actionValue);}
 for(const node of role('profile-name')){const input=node.querySelector('input');if(input&&document.activeElement!==input)input.value=state.profile;else if(!input)setText(node,state.profile);}for(const node of role('order-id'))setText(node,last?'#'+last.id:t('سفارشی ثبت نشده است.','No orders yet.'));for(const node of role('order-summary'))setText(node,last?last.items.map(p=>p.quantity+' × '+p.title+(p.size?' · '+p.size:'')).join('\n')+'\n'+money(last.total)+(last.shipping?.address?'\n'+last.shipping.city+' · '+last.shipping.address:''):t('سفارشی ثبت نشده است.','No orders yet.'));
 for(const node of role('search')){const input=node.querySelector('input');if(input&&input!==document.activeElement)input.value=state.query;}for(const key of ['rating','size','color','brand'])for(const node of role('filter-'+key)){const select=node.querySelector('select');if(select)select.value=state.filters[key]||'';}
 const cards=role('product-card');let empty=root.querySelector('.commerce-no-results');if(cards.length){if(!empty){empty=document.createElement('p');empty.className='commerce-no-results';empty.textContent=t('محصولی با این جست‌وجو و فیلتر پیدا نشد.','No products match these filters.');cards[0].parentElement.after(empty);}empty.hidden=cards.some(card=>!card.hidden);}
 }
 function placeOrder(form){if(!Object.values(state.cart).some(q=>q>0)){showStatus(t('ابتدا محصولی به سبد اضافه کنید.','Add a product to your cart first.'));return;}if(!form.reportValidity())return;const values={};for(const node of form.querySelectorAll('[data-commerce-role]')){const control=node.querySelector('input,select,textarea');if(control)values[node.dataset.commerceRole]=control.value.trim();}if(['name','phone','address','city','postal'].some(key=>!values['checkout-'+key])){const error=role('checkout-error')[0];if(error)setText(error,t('اطلاعات تحویل را کامل کنید.','Complete your shipping details.'));return;}
 const items=products.filter(p=>state.cart[p.id]).map(p=>({title:p.title,quantity:state.cart[p.id],price:p.price,...state.variants[p.id]})),order={id:sceneId().slice(1,9).toUpperCase(),createdAt:Date.now(),status:'local',total:commerceTotal(state,products),shipping:Object.fromEntries(['name','phone','address','city','postal','payment'].map(key=>[key,values['checkout-'+key]||''])),items};const previous=JSON.parse(JSON.stringify(state));state.orders.unshift(order);state.orders=state.orders.slice(0,30);state.cart={};if(!persist()){Object.assign(state,previous);return;}onPage('success');
 }
 const click=e=>{const button=e.target.closest('[data-commerce-action]');if(!button)return;e.preventDefault();e.stopPropagation();const action=button.dataset.commerceAction,id=button.dataset.itemId,product=getProduct(id);if(action==='place-order'){const form=button.closest('form');if(form)placeOrder(form);return;}
 if(['cart-add','cart-plus','cart-minus','cart-remove'].includes(action)&&product){const delta=action==='cart-minus'?-1:1;state.cart[id]=action==='cart-remove'?0:Math.max(0,Math.min(product.stock??99,99,(state.cart[id]||0)+delta));if(!state.cart[id])delete state.cart[id];if(action==='cart-add')showStatus(t('به سبد اضافه شد.','Added to your cart.'));}
 if(action==='favorite'&&product){state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];}
 if((action==='variant-size'||action==='variant-color')&&product){state.variants[id]||={};state.variants[id][action==='variant-size'?'size':'color']=button.dataset.actionValue;}
 if(action==='profile-save'){const input=role('profile-name').map(n=>n.querySelector('input')).find(Boolean);if(input?.value.trim())state.profile=input.value.trim().slice(0,80);showStatus(t('نام ذخیره شد.','Name saved.'));}
 if(action==='clear-filters'){state.filters={};state.query='';persist();onPage('catalog');return;}if(action==='apply-filters'){persist();onPage('catalog');return;}persist();refresh();};
 const input=e=>{const node=e.target.closest('[data-commerce-role]');if(!node)return;const kind=node.dataset.commerceRole;if(kind==='search'){state.query=e.target.value.slice(0,200);persist();refresh();}if(kind.startsWith('filter-')){state.filters[kind.slice(7)]=e.target.value;persist();}};
 const submit=e=>{const form=e.target.closest('[data-commerce-form="checkout"]');if(form){e.preventDefault();e.stopPropagation();placeOrder(form);}};
 const searchKey=e=>{if(e.key==='Enter'&&e.target.closest('[data-commerce-role="search"]')){e.preventDefault();onPage('catalog');}};root.addEventListener('keydown',searchKey);root.addEventListener('click',click);root.addEventListener('input',input);root.addEventListener('change',input);root.addEventListener('submit',submit);refresh();const timer=root.querySelector('[data-scene-frame="splash"]')?setTimeout(()=>onPage('home'),1100):null;
 return ()=>{if(timer)clearTimeout(timer);root.removeEventListener('keydown',searchKey);root.removeEventListener('click',click);root.removeEventListener('input',input);root.removeEventListener('change',input);root.removeEventListener('submit',submit);};
}

export function parseCommercePrice(value){return Number(String(value||'').replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[^\d.]/g,''))||0;}

