export const persianDigits=value=>String(value??'').replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[Number(d)]);
export function persianCommerceText(value){const text=String(value??'');if(Object.prototype.hasOwnProperty.call(commercePersianDictionary,text))return commercePersianDictionary[text];if(/^\$[\d,.]+$/.test(text))return persianDigits(text.slice(1))+' دلار';let out=text;for(const [from,to] of Object.entries(commercePersianDictionary).sort((a,b)=>b[0].length-a[0].length)){if(out.includes(from))out=out.split(from).join(to);}out=out.replace(/Stocks Left/g,'عدد باقی‌مانده').replace(/View your cart/g,'مشاهده سبد').replace(/Filter/g,'فیلتر').replace(/Rating/g,'امتیاز').replace(/Size/g,'اندازه').replace(/Color/g,'رنگ').replace(/Brand/g,'برند');return persianDigits(out.replace(/K\+/g,' هزار+').replace(/([0-9])x/g,'$1 کالا'));}
export function localizeCommerceProject(c){if(!['shopcart','brewbliss','swimshop'].includes(c.template)||c.localeVersion===2)return c;c.lang='fa';c.localeVersion=2;for(const key of ['name','tagline','description','about'])c[key]=persianCommerceText(c[key]);for(const item of c.items||[])for(const key of ['title','description','category','price'])item[key]=persianCommerceText(item[key]);if(c.scene){c.scene.localeVersion=2;for(const page of c.scene.pages){page.name=persianCommerceText(page.name);page.direction='rtl';page.fontFamily='inherit';const walk=(nodes,parent)=>{for(const n of nodes){n.direction='rtl';n.fontFamily='inherit';if(n.align==='left')n.align='right';for(const key of ['text','fieldLabel','options'])if(n[key])n[key]=persianCommerceText(n[key]);if(['absolute','fixed'].includes(n.position)){n.anchor=({'top-left':'top-right','top-right':'top-left','bottom-left':'bottom-right','bottom-right':'bottom-left'})[n.anchor]||n.anchor;[n.insetLeft,n.insetRight]=[n.insetRight,n.insetLeft];}else if(parent.layout==='free')n.x=n.widthMode==='fill'?0:Math.max(0,parent.w-n.x-n.w);if(n.type==='button'&&n.iconStack)n.iconGap=3;if(['arrow-left','arrow-right','chevron-left','chevron-right'].includes(n.iconName))n.iconName=({'arrow-left':'arrow-right','arrow-right':'arrow-left','chevron-left':'chevron-right','chevron-right':'chevron-left'})[n.iconName];walk(n.children||[],n);}};walk(page.children,page);}if(c.scene.commerce)for(const product of c.scene.commerce.products){product.title=persianCommerceText(product.title);product.category=persianCommerceText(product.category);}}return c;}
